import { requireAdminPage } from "@/lib/admin/page-auth";
import { listAudit } from "@/lib/admin/queries";
import { actions } from "@/lib/admin/contracts";
import { AuditTable } from "@/components/admin/audit-table";
import { AdminNotice, CursorLink } from "@/components/admin/common";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
export default async function AuditPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  await requireAdminPage();
  const params = await searchParams,
    filters = Object.fromEntries(
      Object.entries(params).filter(([, v]) => v !== ""),
    );
  let data;
  try {
    data = await listAudit(filters);
  } catch {
    return <AdminNotice />;
  }
  return (
    <>
      <h1 className="text-3xl font-semibold">Audit history</h1>
      <p>
        Append-only metadata. Legacy free-text and arbitrary data are excluded.
      </p>
      <form className="flex flex-wrap items-end gap-4">
        <label>
          Actor UUID
          <Input
            name="actorId"
            defaultValue={(params.actorId as string) ?? ""}
          />
        </label>
        <label>
          Target UUID
          <Input
            name="targetId"
            defaultValue={(params.targetId as string) ?? ""}
          />
        </label>
        <label>
          Action
          <select
            name="action"
            defaultValue={(params.action as string) ?? ""}
            className="block min-h-11 border bg-surface px-3"
          >
            <option value="">All actions</option>
            {actions.map((a) => (
              <option key={a}>{a}</option>
            ))}
          </select>
        </label>
        <Button>Apply filters</Button>
      </form>
      <AuditTable events={data.events} />
      <CursorLink
        path="/admin/audit"
        cursor={data.nextCursor}
        filters={filters as Record<string, string>}
      />
    </>
  );
}
